1	// Contract tests for resources/jusprin/ui/design-tokens.json, the file every
2	// JusPrin color, radius, spacing step, and type role resolves through (shell,
3	// Agent page, and the OrcaSlicer palette overrides in
4	// JusPrin/Brand/BrandPalette.cpp). The scale cases below are the numbers in
5	// agent-docs/jusprin/design-system.md; change both or neither.
6	
7	#include <catch2/catch_all.hpp>
8	
9	#include <nlohmann/json.hpp>
10	
11	#include <algorithm>
12	#include <cmath>
13	#include <fstream>
14	#include <functional>
15	#include <map>
16	#include <set>
17	#include <string>
18	#include <vector>
19	
20	using nlohmann::json;
21	
22	namespace {
23	
24	json load_tokens()
25	{
26	    std::ifstream file(std::string(JUSPRIN_SOURCE_DIR) + "/resources/jusprin/ui/design-tokens.json");
27	    REQUIRE(file.is_open());
28	    return json::parse(file);
29	}
30	
31	struct Rgb { double r, g, b; };
32	
33	Rgb parse_hex(const std::string& hex)
34	{
35	    REQUIRE(hex.size() == 7);
36	    REQUIRE(hex[0] == '#');
37	    auto channel = [&](size_t at) { return std::stoi(hex.substr(at, 2), nullptr, 16) / 255.0; };
38	    return {channel(1), channel(3), channel(5)};
39	}
40	
41	// WCAG 2 relative luminance and contrast ratio.
42	double linear(double c) { return c <= 0.03928 ? c / 12.92 : std::pow((c + 0.055) / 1.055, 2.4); }
43	double luminance(const Rgb& c) { return 0.2126 * linear(c.r) + 0.7152 * linear(c.g) + 0.0722 * linear(c.b); }
44	double contrast(const std::string& a, const std::string& b)
45	{
46	    const double la = luminance(parse_hex(a)), lb = luminance(parse_hex(b));
47	    return (std::max(la, lb) + 0.05) / (std::min(la, lb) + 0.05);
48	}
49	
50	} // namespace
51	
52	TEST_CASE("every semantic token is a six-digit hex color in both modes", "[brand]")
53	{
54	    const json tokens = load_tokens();
55	    for (const char* mode : {"light", "dark"}) {
56	        const json& semantic = tokens.at("semantic").at(mode);
57	        for (const auto& [group, values] : semantic.items())
58	            for (const auto& [name, value] : values.items()) {
59	                INFO(mode << "." << group << "." << name);
60	                REQUIRE(value.is_string());
61	                parse_hex(value.get<std::string>());
62	            }
63	    }
64	}
65	
66	TEST_CASE("text keeps the documented contrast on every surface", "[brand]")
67	{
68	    const json tokens = load_tokens();
69	    for (const char* mode : {"light", "dark"}) {
70	        const json& s = tokens.at("semantic").at(mode);
71	        for (const char* surface : {"canvas", "subtle", "raised", "selected"}) {
72	            const std::string bg = s.at("surface").at(surface);
73	            INFO(mode << " text on surface." << surface << " (" << bg << ")");
74	            CHECK(contrast(s.at("text").at("primary"), bg) >= 4.5);
75	            CHECK(contrast(s.at("text").at("secondary"), bg) >= 4.5);
76	            // Dark tertiary on the selected surface is a known gap; see the
77	            // [!mayfail] case below.
78	            if (std::string(mode) == "light" || std::string(surface) != "selected")
79	                CHECK(contrast(s.at("text").at("tertiary"), bg) >= 4.5);
80	        }
81	        // Essential boundaries need 3:1 on the surfaces a control normally sits on.
82	        for (const char* surface : {"canvas", "subtle", "raised"}) {
83	            const std::string bg = s.at("surface").at(surface);
84	            INFO(mode << " borders on surface." << surface << " (" << bg << ")");
85	            CHECK(contrast(s.at("border").at("strong"), bg) >= 3.0);
86	            CHECK(contrast(s.at("border").at("focus"), bg) >= 3.0);
87	        }
88	    }
89	}
90	
91	// Known token gaps, reported rather than hidden: in dark mode the focus ring
92	// (#7D6A8D) on the selected surface (#4B3E57) measures about 2.0:1, below the
93	// 3:1 the design system promises for state indicators, and dark tertiary text
94	// (#A99EAE) on the same surface measures about 3.9:1, below 4.5:1. Resolving
95	// them is a token decision; this case turns green on its own once the tokens
96	// change.
97	TEST_CASE("focus ring and tertiary text stay visible on the selected surface", "[brand][!mayfail]")
98	{
99	    const json tokens = load_tokens();
100	    for (const char* mode : {"light", "dark"}) {
101	        const json& s = tokens.at("semantic").at(mode);
102	        const std::string bg = s.at("surface").at("selected");
103	        INFO(mode << " on surface.selected (" << bg << ")");
104	        CHECK(contrast(s.at("border").at("focus"), bg) >= 3.0);
105	        CHECK(contrast(s.at("text").at("tertiary"), bg) >= 4.5);
106	    }
107	}
108	
109	TEST_CASE("action text is readable on the action fill in every state", "[brand]")
110	{
111	    const json tokens = load_tokens();
112	    for (const char* mode : {"light", "dark"}) {
113	        const json& a = tokens.at("semantic").at(mode).at("action");
114	        for (const char* fill : {"primary", "primaryHover", "primaryPressed"}) {
115	            INFO(mode << " action." << fill);
116	            CHECK(contrast(a.at("primaryText"), a.at(fill)) >= 4.5);
117	        }
118	        CHECK(contrast(a.at("secondaryText"), a.at("secondary")) >= 4.5);
119	        CHECK(contrast(a.at("dangerText"), a.at("danger")) >= 4.5);
120	        CHECK(contrast(tokens.at("semantic").at(mode).at("status").at("successOnAction"), a.at("primary")) >= 3.0);
121	        // Disabled controls are exempt from the contrast minimum (WCAG 1.4.3);
122	        // only guard against a fully invisible label.
123	        CHECK(contrast(a.at("disabledText"), a.at("disabled")) >= 2.0);
124	    }
125	}
126	
127	TEST_CASE("dark mode is a remapping, not a copy of light mode", "[brand]")
128	{
129	    const json tokens = load_tokens();
130	    const json& light = tokens.at("semantic").at("light");
131	    const json& dark  = tokens.at("semantic").at("dark");
132	    CHECK(light.at("surface").at("canvas") != dark.at("surface").at("canvas"));
133	    CHECK(light.at("action").at("primary") != dark.at("action").at("primary"));
134	    // The same token names exist in both modes so a component can switch by
135	    // mode alone: a token added to one mode must be added to the other.
136	    auto require_mirror = [](const json& from, const char* from_mode, const json& to, const char* to_mode) {
137	        for (const auto& [group, values] : from.items())
138	            for (const auto& [name, value] : values.items()) {
139	                INFO("semantic." << from_mode << "." << group << "." << name
140	                     << " has no counterpart in semantic." << to_mode);
141	                CHECK((to.contains(group) && to.at(group).contains(name)));
142	            }
143	    };
144	    require_mirror(light, "light", dark, "dark");
145	    require_mirror(dark, "dark", light, "light");
146	}
147	
148	// The scale cases pin the tables in agent-docs/jusprin/design-system.md.
149	// Each one names the offending key so a wrong edit is a one-line fix.
150	
151	template <typename T>
152	void require_exact_table(const json& actual, const std::map<std::string, T>& expected, const std::string& path)
153	{
154	    for (const auto& [key, value] : expected) {
155	        INFO(path << "." << key << " expected " << value);
156	        REQUIRE(actual.contains(key));
157	        CHECK(actual.at(key) == json(value));
158	    }
159	    for (const auto& [key, value] : actual.items()) {
160	        INFO(path << "." << key << " is not part of the scale");
161	        CHECK(expected.count(key) == 1);
162	    }
163	}
164	
165	TEST_CASE("the radius scale is exactly the documented one", "[brand]")
166	{
167	    const json tokens = load_tokens();
168	    require_exact_table<int>(tokens.at("dimension").at("radius"),
169	        {{"standard", 4}, {"compact", 8}, {"container", 8}, {"window", 12}, {"pill", 9999}},
170	        "dimension.radius");
171	}
172	
173	TEST_CASE("the spacing scale is exactly the documented one", "[brand]")
174	{
175	    const json tokens = load_tokens();
176	    require_exact_table<int>(tokens.at("dimension").at("space"),
177	        {{"1", 4}, {"2", 8}, {"3", 12}, {"4", 16}, {"5", 20}, {"6", 24}, {"8", 32}, {"10", 40}, {"12", 48}},
178	        "dimension.space");
179	    std::vector<int> values;
180	    for (const auto& [key, value] : tokens.at("dimension").at("space").items())
181	        values.push_back(value.get<int>());
182	    std::sort(values.begin(), values.end());
183	    CHECK(values == std::vector<int>{4, 8, 12, 16, 20, 24, 32, 40, 48});
184	}
185	
186	TEST_CASE("the type roles are exactly the documented ones", "[brand]")
187	{
188	    const json tokens = load_tokens();
189	    const json& roles = tokens.at("typography").at("roles");
190	    const std::map<std::string, json> expected = {
191	        {"pageTitle", {{"size", 24}, {"lineHeight", 30}, {"weight", 700}}},
192	        {"section",   {{"size", 18}, {"lineHeight", 24}, {"weight", 700}}},
193	        {"body",      {{"size", 14}, {"lineHeight", 20}, {"weight", 400}}},
194	        {"bodyBold",  {{"size", 14}, {"lineHeight", 20}, {"weight", 700}}},
195	        {"label",     {{"size", 12}, {"lineHeight", 16}, {"weight", 400}}},
196	        {"labelBold", {{"size", 12}, {"lineHeight", 16}, {"weight", 700}}},
197	        {"metadata",  {{"size", 10}, {"lineHeight", 14}, {"weight", 400}}},
198	    };
199	    for (const auto& [role, spec] : expected) {
200	        INFO("typography.roles." << role);
201	        REQUIRE(roles.contains(role));
202	        for (const auto& [field, value] : spec.items()) {
203	            INFO("typography.roles." << role << "." << field << " expected " << value);
204	            CHECK(roles.at(role).value(field, json()) == value);
205	        }
206	    }
207	    for (const auto& [role, spec] : roles.items()) {
208	        INFO("typography.roles." << role << " is not a documented role");
209	        CHECK(expected.count(role) == 1);
210	    }
211	}
212	
213	TEST_CASE("button recipes name a type role instead of a raw size", "[brand]")
214	{
215	    const json tokens = load_tokens();
216	    std::set<std::string> roles;
217	    for (const auto& [role, spec] : tokens.at("typography").at("roles").items())
218	        roles.insert(role);
219	    for (const auto& [name, recipe] : tokens.at("component").at("button").items()) {
220	        INFO("component.button." << name);
221	        CHECK_FALSE(recipe.contains("textSize"));
222	        if (recipe.contains("textRole")) {
223	            INFO("component.button." << name << ".textRole = " << recipe.at("textRole"));
224	            REQUIRE(recipe.at("textRole").is_string());
225	            CHECK(roles.count(recipe.at("textRole").get<std::string>()) == 1);
226	        }
227	    }
228	}
229	
230	TEST_CASE("the Agent pane resize geometry is explicit", "[brand]")
231	{
232	    const json tokens = load_tokens();
233	    const json& pane = tokens.at("component").at("agentPane");
234	    require_exact_table<int>(pane,
235	        {{"minWidth", 320}, {"workspaceMinWidth", 320}, {"resizeHandleWidth", 8},
236	         {"resizeHandleLineWidth", 2}},
237	        "component.agentPane");
238	}
239	
240	TEST_CASE("every component radius comes from the radius scale", "[brand]")
241	{
242	    const json tokens = load_tokens();
243	    std::set<int> allowed = {0}; // menu rows carry no radius inside an already-rounded popover
244	    for (const auto& [name, value] : tokens.at("dimension").at("radius").items())
245	        allowed.insert(value.get<int>());
246	    int checked = 0;
247	    std::function<void(const json&, const std::string&)> walk = [&](const json& node, const std::string& path) {
248	        for (const auto& [key, value] : node.items()) {
249	            const std::string here = path + "." + key;
250	            if (key == "radius") {
251	                INFO(here << " = " << value << " is not a dimension.radius value");
252	                REQUIRE(value.is_number_integer());
253	                CHECK(allowed.count(value.get<int>()) == 1);
254	                ++checked;
255	            } else if (value.is_object()) {
256	                walk(value, here);
257	            }
258	        }
259	    };
260	    walk(tokens.at("component"), "component");
261	    CHECK(checked >= 10);
262	}
263	
264	TEST_CASE("the CSS font stacks are present", "[brand]")
265	{
266	    const json tokens = load_tokens();
267	    const json& typography = tokens.at("typography");
268	    for (const auto& [path, value] : {
269	             std::pair<const char*, json>{"typography.ui.cssFallback", typography.at("ui").value("cssFallback", json())},
270	             std::pair<const char*, json>{"typography.technical.cssFamily", typography.at("technical").value("cssFamily", json())}}) {
271	        INFO(path);
272	        REQUIRE(value.is_string());
273	        CHECK_FALSE(value.get<std::string>().empty());
274	    }
275	}
276

