from fontTools.ttLib import TTFont
for f in ['resources/fonts/HarmonyOS_Sans_SC_Regular.ttf','resources/fonts/HarmonyOS_Sans_SC_Bold.ttf','src/slic3r/GUI/JusPrin/AgentUI/src/fonts/HarmonyOS_Sans_SC_Regular_latin.woff']:
    t=TTFont(f); cmap=t.getBestCmap(); hm=t['hmtx']
    w={c:hm[cmap[ord(c)]][0] for c in '0123456789'}
    feats=set()
    if 'GSUB' in t and t['GSUB'].table.FeatureList:
        feats={r.FeatureTag for r in t['GSUB'].table.FeatureList.FeatureRecord}
    print(f.split('/')[-1], 'digit widths:', sorted(set(w.values())), 'tnum' in feats and 'has tnum' or 'no tnum', 'pnum' in feats and 'has pnum' or '')
EOF

