content.content:
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}

/* Shares the compact radius and height of the primary button beside it so
   the key row reads as one control. A key is a technical value. */
.setup-key-input {
  flex: 1;
  min-width: 0;
  padding: var(--button-secondary-padding);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-compact);
  background: var(--surface-canvas);
  color: var(--text-primary);
  font: var(--font-mono-label);
}

.setup-key-input:focus {
  outline: 2px solid var(--border-focus);
  background: var(--surface-subtle);
}

/* The degenerate case: nothing delegated, nothing sliced, preset untouched.
   A label is not a card, so it keeps the slot but drops the frame. */
.current-setup.bare {
  padding: 0 4px;
  border: 0;
  border-radius: 0;
  background: transparent;
  font: var(--font-mono-metadata);
  color: var(--text-secondary);
}

