93	/* The degenerate case: nothing delegated, nothing sliced, preset untouched.
94	   A label is not a card, so it keeps the slot but drops the frame. */
95	.current-setup.bare {
96	  padding: 0 4px;
97	  border: 0;
98	  border-radius: 0;
99	  background: transparent;
100	  font: var(--font-mono-metadata);
101	  color: var(--text-secondary);
102	}
103	
104	.current-setup p {
105	  margin: 0;
106	}
107	
108	/* Eyebrow in Dense Metadata, action/primary. The right half is where a state
109	   puts its one word -- "working...", "+2 yours", "undo" -- so nothing else may
110	   live there. */
111	.current-setup-eyebrow {
112	  display: flex;
113	  align-items: center;
114	  justify-content: space-between;
115	  gap: 8px;
116	  font: var(--font-metadata);
117	  letter-spacing: 0.06em;
118	  text-transform: uppercase;
119	  color: var(--action-primary);
120	  /* One line, always. Measured at the dock's real width -- which narrows with
121	     the window, well below the 429px design frame -- a three-digit count wraps
122	     the heading and the card silently grows a row. The fixed word gives up a
123	     few pixels instead, because losing height is worse than losing them. */
124	  white-space: nowrap;
125	}
126	
127	.current-setup-eyebrow > span:first-child {
128	  min-width: 0;
129	  overflow: hidden;
130	  text-overflow: ellipsis;
131	}
132	
133	/* Mid-thought: everything drops to secondary, nothing is removed. The numbers
134	   on screen are still what Slice would produce this second. */
135	.current-setup.working .current-setup-title,
136	.current-setup.working .current-setup-identity {
137	  color: var(--text-secondary);
138	}
139	
140	.current-setup.working.bare {
141	  opacity: 0.7;
142	}
143	
144	/* The figure the plate can no longer defend. Kept legible: it is the number
145	   the reader is comparing the new one against. */
146	.current-setup-cost .superseded {
147	  text-decoration: line-through;
148	  opacity: 0.7;
149	}
150	
151	/* Out of date drops the edge entirely, as the design has it: the card is not
152	   asking for attention, it is standing down from a number it cannot defend.
153	   Transparent rather than removed so the box keeps its size. */
154	.current-setup.out-of-date {
155	  border-color: transparent;
156	}
157	
158	/* Why it went, then what to do. Its own row: the dock narrows with the window,
159	   well below the 429px design frame, and sharing the facts line cost this its
160	   second half in the running app. A truncated instruction is worse than 16px. */
161	.current-setup-note {
162	  font: var(--font-metadata);
163	  color: var(--text-secondary);
164	  white-space: nowrap;
165	  overflow: hidden;
166	  text-overflow: ellipsis;
167	}
168	
169	/* Colour alone marks the action, as it does on every other accent control in
170	   the panel. There is no bold metadata role, and inheriting a larger bold role
171	   inline would inflate the row it sits in. */
172	.current-setup-note .action {
173	  color: var(--action-primary);
174	}
175	
176	.current-setup-eyebrow .out-of-date {
177	  color: var(--status-warning);
